    p12.[GeoPostalCodeName] AS [Supplier_GeoPostalCode_GeoPostalCodeName],
    p13.[GeoCityCode] AS [Supplier_GeoPostalCode_GeoCity_GeoCityCode],
    p13.[GeoCityName] AS [Supplier_GeoPostalCode_GeoCity_GeoCityName],
    p14.[GeoStateProvinceCode] AS [Supplier_GeoPostalCode_GeoCity_GeoStateProvince_GeoStateProvinceCode],
    p14.[GeoStateProvinceName] AS [Supplier_GeoPostalCode_GeoCity_GeoStateProvince_GeoStateProvinceName],
    p15.[GeoCountryCode] AS [Supplier_GeoPostalCode_GeoCity_GeoStateProvince_GeoCountry_GeoCountryCode],
    p15.[GeoCountryName] AS [Supplier_GeoPostalCode_GeoCity_GeoStateProvince_GeoCountry_GeoCountryName],
    p16.[GeoContinentCode] AS [Supplier_GeoPostalCode_GeoCity_GeoStateProvince_GeoCountry_GeoContinent_GeoContinentCode],
    p16.[GeoContinentName] AS [Supplier_GeoPostalCode_GeoCity_GeoStateProvince_GeoCountry_GeoContinent_GeoContinentName],
    p17.[SupplierCategoryCode] AS [Supplier_SupplierCategory_SupplierCategoryCode],
    p17.[SupplierCategoryName] AS [Supplier_SupplierCategory_SupplierCategoryName],
    p17.[OwnerName] AS [Supplier_SupplierCategory_OwnerName],
    p18.[PaymentTermCode] AS [Supplier_SupplierCategory_PaymentTerm_PaymentTermCode],
    p18.[PaymentTermName] AS [Supplier_SupplierCategory_PaymentTerm_PaymentTermName],
    p19.[StatusCode] AS [Supplier_SupplierCategory_RecordStatus_StatusCode],
    p19.[StatusName] AS [Supplier_SupplierCategory_RecordStatus_StatusName],
    p20.[RiskClassCode] AS [Supplier_SupplierRiskClass_RiskClassCode],
    p20.[RiskClassName] AS [Supplier_SupplierRiskClass_RiskClassName],
    p20.[OwnerName] AS [Supplier_SupplierRiskClass_OwnerName],
    p21.[StatusCode] AS [Supplier_SupplierRiskClass_RecordStatus_StatusCode],
    p21.[StatusName] AS [Supplier_SupplierRiskClass_RecordStatus_StatusName],
    p22.[SeverityCode] AS [Supplier_SupplierRiskClass_Severity_SeverityCode],
    p22.[SeverityName] AS [Supplier_SupplierRiskClass_Severity_SeverityName],
    p23.[SupplierTierCode] AS [Supplier_SupplierTier_SupplierTierCode],
    p23.[SupplierTierName] AS [Supplier_SupplierTier_SupplierTierName],
    p23.[OwnerName] AS [Supplier_SupplierTier_OwnerName],
    p24.[StatusCode] AS [Supplier_SupplierTier_RecordStatus_StatusCode],
    p24.[StatusName] AS [Supplier_SupplierTier_RecordStatus_StatusName]
FROM [dim].[PurchaseSupplierScorecard] b
LEFT JOIN [dim].[PurchaseCommodity] p1 ON b.[PurchaseCommodityKey] = p1.[PurchaseCommodityKey]
LEFT JOIN [dim].[PurchaseCommoditySubcategory] p2 ON p1.[PurchaseCommoditySubcategoryKey] = p2.[PurchaseCommoditySubcategoryKey]
LEFT JOIN [dim].[PurchaseCommodityCategory] p3 ON p2.[PurchaseCommodityCategoryKey] = p3.[PurchaseCommodityCategoryKey]
LEFT JOIN [dim].[PurchaseCommodityDomain] p4 ON p3.[PurchaseCommodityDomainKey] = p4.[PurchaseCommodityDomainKey]
LEFT JOIN [dim].[Supplier] p5 ON b.[SupplierKey] = p5.[SupplierKey]
LEFT JOIN [ref].[Currency] p6 ON p5.[CurrencyKey] = p6.[CurrencyKey]
LEFT JOIN [ref].[CurrencyRegion] p7 ON p6.[CurrencyRegionKey] = p7.[CurrencyRegionKey]
LEFT JOIN [ref].[IncotermCode] p8 ON p5.[IncotermCodeKey] = p8.[IncotermCodeKey]
LEFT JOIN [ref].[PaymentTerm] p9 ON p5.[PaymentTermKey] = p9.[PaymentTermKey]
LEFT JOIN [ref].[RecordStatus] p10 ON p5.[RecordStatusKey] = p10.[RecordStatusKey]
LEFT JOIN [ref].[SupplierQualificationStatus] p11 ON p5.[SupplierQualificationStatusKey] = p11.[SupplierQualificationStatusKey]
LEFT JOIN [dim].[GeoPostalCode] p12 ON p5.[GeoPostalCodeKey] = p12.[GeoPostalCodeKey]
LEFT JOIN [dim].[GeoCity] p13 ON p12.[GeoCityKey] = p13.[GeoCityKey]
LEFT JOIN [dim].[GeoStateProvince] p14 ON p13.[GeoStateProvinceKey] = p14.[GeoStateProvinceKey]
LEFT JOIN [dim].[GeoCountry] p15 ON p14.[GeoCountryKey] = p15.[GeoCountryKey]
LEFT JOIN [dim].[GeoContinent] p16 ON p15.[GeoContinentKey] = p16.[GeoContinentKey]
LEFT JOIN [dim].[SupplierCategory] p17 ON p5.[SupplierCategoryKey] = p17.[SupplierCategoryKey]
LEFT JOIN [ref].[PaymentTerm] p18 ON p17.[PaymentTermKey] = p18.[PaymentTermKey]
LEFT JOIN [ref].[RecordStatus] p19 ON p17.[RecordStatusKey] = p19.[RecordStatusKey]
LEFT JOIN [dim].[SupplierRiskClass] p20 ON p5.[SupplierRiskClassKey] = p20.[SupplierRiskClassKey]
LEFT JOIN [ref].[RecordStatus] p21 ON p20.[RecordStatusKey] = p21.[RecordStatusKey]
LEFT JOIN [ref].[Severity] p22 ON p20.[SeverityKey] = p22.[SeverityKey]
LEFT JOIN [dim].[SupplierTier] p23 ON p5.[SupplierTierKey] = p23.[SupplierTierKey]
LEFT JOIN [ref].[RecordStatus] p24 ON p23.[RecordStatusKey] = p24.[RecordStatusKey]
